#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_pipeline.h>
#define BLOCK_THREADS 256
#define TILE_H 16
#define TILE_W 64
#define THREADS_Y 8
#define THREADS_X 32
#define REG_H 2
#define REG_W 2
#define IC_CHUNK 2
#define STAGES 2
#define OC_TILE 16
#define OC_PAD 20
// Asynchronously stage one input/weight chunk into shared memory.
// Valid global elements are transferred with cp.async, while padded
// elements are explicitly zero-filled.
__device__ __forceinline__ void stage_conv_chunk(
    const float* __restrict__ in_base,
    const float* __restrict__ weight,
    float* __restrict__ s_input_stage,
    float* __restrict__ s_weight_stage,
    int oc0, int ic0, int icn,
    int in_ch, int out_ch,
    int H, int W,
    int h0, int w0,
    int halo_h, int halo_w,
    int wchunk)
{
    const int tile_elems = icn * halo_h * halo_w;
    for (int i = threadIdx.x; i < tile_elems; i += blockDim.x) {
        const int c  = i / (halo_h * halo_w);
        const int r  = (i / halo_w) % halo_h;
        const int cc = i % halo_w;
        const int h_in = h0 + r;
        const int w_in = w0 + cc;
        if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
            const float* src = in_base + ((long)(ic0 + c) * H + h_in) * W + w_in;
            __pipeline_memcpy_async(s_input_stage + i, src, sizeof(float));
        } else {
            s_input_stage[i] = 0.0f;
        }
    }
    const int w_elems = OC_TILE * IC_CHUNK * wchunk;
    for (int i = threadIdx.x; i < w_elems; i += blockDim.x) {
        const int o = i / (IC_CHUNK * wchunk);
        const int r = i % (IC_CHUNK * wchunk);
        const int c = r / wchunk;
        const int k = r % wchunk;
        const int dst = (c * wchunk + k) * OC_PAD + o;
        if (oc0 + o < out_ch && c < icn) {
            const float* src = weight + ((long)(oc0 + o) * in_ch + ic0 + c) * wchunk + k;
            __pipeline_memcpy_async(s_weight_stage + dst, src, sizeof(float));
        } else {
            s_weight_stage[dst] = 0.0f;
        }
    }
    __pipeline_commit();
}
// Tiled direct convolution kernel with double-buffered asynchronous staging.
// While the current input-channel chunk is consumed from shared memory, the
// next chunk is transferred into the alternate shared-memory buffer.
__global__ void __launch_bounds__(BLOCK_THREADS, 2) conv2d_direct_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch, int in_ch, int out_ch,
    int H, int W, int H_out, int W_out,
    int kh, int kw,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int stride_h, int stride_w)
{
    const int halo_h = (TILE_H - 1) * stride_h + (kh - 1) * dil_h + 1;
    const int halo_w = (TILE_W - 1) * stride_w + (kw - 1) * dil_w + 1;
    const int wchunk = kh * kw;
    const int input_stage_elems = IC_CHUNK * halo_h * halo_w;
    const int weight_stage_elems = OC_PAD * IC_CHUNK * wchunk;
    extern __shared__ __align__(16) float smem[];
    float* s_input  = smem;
    float* s_weight = smem + STAGES * input_stage_elems;
    const int oc0 = blockIdx.y * OC_TILE;
    const int b   = blockIdx.z;
    const int tiles_x = (W_out + TILE_W - 1) / TILE_W;
    const int tile    = blockIdx.x;
    const int th0     = (tile / tiles_x) * TILE_H;
    const int tw0     = (tile % tiles_x) * TILE_W;
    const int h0 = th0 * stride_h - pad_h;
    const int w0 = tw0 * stride_w - pad_w;
    const float* in_base = input + (long)b * in_ch * H * W;
    const int ty = threadIdx.x / THREADS_X;
    const int tx = threadIdx.x % THREADS_X;
    const int oy0 = ty * REG_H;
    const int ox0 = tx * REG_W;
    const int h_out0 = th0 + oy0;
    const int h_out1 = th0 + oy0 + 1;
    const int w_out0 = tw0 + ox0;
    const int w_out1 = tw0 + ox0 + 1;
    const bool valid00 = (h_out0 < H_out) && (w_out0 < W_out);
    const bool valid01 = (h_out0 < H_out) && (w_out1 < W_out);
    const bool valid10 = (h_out1 < H_out) && (w_out0 < W_out);
    const bool valid11 = (h_out1 < H_out) && (w_out1 < W_out);
    float sum[OC_TILE][4];
    #pragma unroll
    for (int o = 0; o < OC_TILE; o++) {
        sum[o][0] = 0.0f;
        sum[o][1] = 0.0f;
        sum[o][2] = 0.0f;
        sum[o][3] = 0.0f;
    }
    int stage = 0;
    const int first_icn = min(IC_CHUNK, in_ch);
    stage_conv_chunk(
        in_base, weight,
        s_input, s_weight,
        oc0, 0, first_icn,
        in_ch, out_ch, H, W,
        h0, w0, halo_h, halo_w, wchunk);
    for (int ic0 = 0; ic0 < in_ch; ic0 += IC_CHUNK) {
        const int icn = min(IC_CHUNK, in_ch - ic0);
        const int next_ic0 = ic0 + IC_CHUNK;
        const int next_stage = stage ^ 1;
        // Ensure all warps have finished reading the buffer that is about to
        // receive the next asynchronous transfer.
        __syncthreads();
        if (next_ic0 < in_ch) {
            const int next_icn = min(IC_CHUNK, in_ch - next_ic0);
            stage_conv_chunk(
                in_base, weight,
                s_input + next_stage * input_stage_elems,
                s_weight + next_stage * weight_stage_elems,
                oc0, next_ic0, next_icn,
                in_ch, out_ch, H, W,
                h0, w0, halo_h, halo_w, wchunk);
            // Leave the newly issued transfer in flight while waiting for
            // the previously issued transfer for the current chunk.
            __pipeline_wait_prior(1);
        } else {
            __pipeline_wait_prior(0);
        }
        __syncthreads();
        const float* cur_input  = s_input + stage * input_stage_elems;
        const float* cur_weight = s_weight + stage * weight_stage_elems;
        for (int c = 0; c < icn; c++) {
            const float* s_in_c = cur_input + c * halo_h * halo_w;
            const float* s_w_c  = cur_weight + c * wchunk * OC_PAD;
            for (int i = 0; i < kh; i++) {
                const int r0 = oy0 * stride_h + i * dil_h;
                const int r1 = r0 + stride_h;
                const float* s_row0 = s_in_c + r0 * halo_w;
                const float* s_row1 = s_in_c + r1 * halo_w;
                for (int j = 0; j < kw; j++) {
                    const int cc0 = ox0 * stride_w + j * dil_w;
                    const int cc1 = cc0 + stride_w;
                    const float v00 = s_row0[cc0];
                    const float v01 = s_row0[cc1];
                    const float v10 = s_row1[cc0];
                    const float v11 = s_row1[cc1];
                    const int widx = i * kw + j;
                    const float4* s_wv = reinterpret_cast<const float4*>(s_w_c + widx * OC_PAD);
                    float wv[OC_TILE];
                    #pragma unroll
                    for (int g = 0; g < OC_TILE / 4; g++) {
                        const float4 t = s_wv[g];
                        wv[4 * g + 0] = t.x;
                        wv[4 * g + 1] = t.y;
                        wv[4 * g + 2] = t.z;
                        wv[4 * g + 3] = t.w;
                    }
                    #pragma unroll
                    for (int o = 0; o < OC_TILE; o++) {
                        sum[o][0] += v00 * wv[o];
                        sum[o][1] += v01 * wv[o];
                        sum[o][2] += v10 * wv[o];
                        sum[o][3] += v11 * wv[o];
                    }
                }
            }
        }
        stage ^= 1;
    }
    #pragma unroll
    for (int o = 0; o < OC_TILE; o++) {
        const int oc = oc0 + o;
        if (oc >= out_ch) break;
        float* out_base = output + ((long)b * out_ch + oc) * H_out * W_out;
        if (valid00) out_base[(long)h_out0 * W_out + w_out0] = sum[o][0];
        if (valid01) out_base[(long)h_out0 * W_out + w_out1] = sum[o][1];
        if (valid10) out_base[(long)h_out1 * W_out + w_out0] = sum[o][2];
        if (valid11) out_base[(long)h_out1 * W_out + w_out1] = sum[o][3];
    }
}
torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight,
                             int64_t stride_h, int64_t stride_w,
                             int64_t pad_h, int64_t pad_w,
                             int64_t dil_h, int64_t dil_w) {
    TORCH_CHECK(input.is_cuda() && weight.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32 &&
                weight.scalar_type() == torch::kFloat32, "float32 required");
    auto input_c  = input.contiguous();
    auto weight_c = weight.contiguous();
    const int batch  = input_c.size(0);
    const int in_ch  = input_c.size(1);
    const int H      = input_c.size(2);
    const int W      = input_c.size(3);
    const int out_ch = weight_c.size(0);
    const int kh     = weight_c.size(2);
    const int kw     = weight_c.size(3);
    const int H_out = (H + 2 * (int)pad_h - (int)dil_h * (kh - 1) - 1) / (int)stride_h + 1;
    const int W_out = (W + 2 * (int)pad_w - (int)dil_w * (kw - 1) - 1) / (int)stride_w + 1;
    auto output = torch::empty({batch, out_ch, H_out, W_out}, input_c.options());
    const int halo_h = (TILE_H - 1) * (int)stride_h + (kh - 1) * (int)dil_h + 1;
    const int halo_w = (TILE_W - 1) * (int)stride_w + (kw - 1) * (int)dil_w + 1;
    const size_t shmem = ((size_t)STAGES * IC_CHUNK * halo_h * halo_w +
                          (size_t)STAGES * OC_PAD * IC_CHUNK * kh * kw) * sizeof(float);
    TORCH_CHECK(shmem <= 96 * 1024, "tile too large for shared memory");
    const int tiles_x = (W_out + TILE_W - 1) / TILE_W;
    const int tiles_y = (H_out + TILE_H - 1) / TILE_H;
    dim3 grid(tiles_x * tiles_y, (out_ch + OC_TILE - 1) / OC_TILE, batch);
    dim3 block(BLOCK_THREADS);
    if (shmem > 48 * 1024) {
        cudaFuncSetAttribute(conv2d_direct_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             (int)shmem);
    }
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    conv2d_direct_kernel<<<grid, block, shmem, stream>>>(
        input_c.data_ptr<float>(),
        weight_c.data_ptr<float>(),
        output.data_ptr<float>(),
        batch, in_ch, out_ch, H, W, H_out, W_out,
        kh, kw,
        (int)pad_h, (int)pad_w,
        (int)dil_h, (int)dil_w,
        (int)stride_h, (int)stride_w);
    return output;
}
'''

