def _pair(x):
    if isinstance(x, tuple):
        return x
    return (x, x)


class ModelNew(nn.Module):
    """
    2D convolution implemented with a custom CUDA kernel.

    The nn.Conv2d submodule is kept only as a parameter holder so that
    initialization and state_dict layout match the reference Model exactly;
    all computation in forward() is performed by the custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size,
                                stride=stride, padding=padding,
                                dilation=dilation, bias=bias)
        self.stride = _pair(stride)
        self.padding = _pair(padding)
        self.dilation = _pair(dilation)
        self.has_bias = bias

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv2d.weight
        if (x.is_cuda and x.dtype == torch.float32 and not self.has_bias):
            return conv2d_module.conv2d_forward(
                x, weight,
                self.stride[0], self.stride[1],
                self.padding[0], self.padding[1],
                self.dilation[0], self.dilation[1])
        # Fallback for non-CUDA / non-float32 / biased configurations.
        return F.conv2d(x, weight, self.conv2d.bias, self.stride,
                        self.padding, self.dilation)

